-- Gate 21A PostgreSQL schema. Apply with a migration runner; do not edit 001_initial.sql.
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, issuer TEXT NOT NULL, subject TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE (issuer, subject));
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL, PRIMARY KEY (organization_id,user_id));
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS evaluation_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), project_id TEXT NOT NULL REFERENCES projects(id), idempotency_key TEXT NOT NULL, status TEXT NOT NULL, provider TEXT NOT NULL, sample_count INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE (organization_id,idempotency_key));
CREATE TABLE IF NOT EXISTS evaluation_results (run_id TEXT PRIMARY KEY REFERENCES evaluation_runs(id), organization_id TEXT NOT NULL REFERENCES organizations(id), result_json JSONB NOT NULL, evidence_metadata_json JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS usage_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), run_id TEXT NOT NULL REFERENCES evaluation_runs(id), units INTEGER NOT NULL, provider_cost_estimate_usd NUMERIC NOT NULL, idempotency_key TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE (organization_id,idempotency_key));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (session_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), issuer TEXT NOT NULL, subject TEXT NOT NULL, csrf_hash TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions (expires_at);
